public sealed record Attempt(string Id, string Tenant, IReadOnlyList<Answer> Answers);
public sealed record Answer(string QuestionId, bool Correct);

public IEnumerable<(string QuestionId, int CorrectCount)> CorrectByQuestion(
    IEnumerable<Attempt> attempts) =>
    attempts
        .SelectMany(a => a.Answers)
        .GroupBy(ans => ans.QuestionId)
        .Select(g => (g.Key, g.Count(a => a.Correct)));

public sealed record Skill(string QuestionId, string Name);

public IEnumerable<string> SkillHits(
    IEnumerable<Answer> answers,
    IEnumerable<Skill> catalog) =>
    from ans in answers
    join skill in catalog on ans.QuestionId equals skill.QuestionId
    where ans.Correct
    select skill.Name;
